using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "echo", Title = "Echo Tool")]
    [Description("Echoes back the provided message.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add", Title = "Add Numbers")]
    [Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;
}

using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "app-config",
        Title = "Application Configuration",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxConnections = 100,
            Features = new { Logging = true, Metrics = true, Tracing = false }
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://status",
        Name = "server-status",
        Title = "Server Status",
        MimeType = "application/json")]
    public static string GetServerStatus()
    {
        var status = new
        {
            Status = "Healthy",
            Uptime = Environment.TickCount64 / 1000,
            MachineName = Environment.MachineName
        };
        return JsonSerializer.Serialize(status, new JsonSerializerOptions { WriteIndented = true });
    }
}

